import json, pathlib
root=pathlib.Path(__file__).parent
q=json.loads((root/'questions.json').read_text())['questions']
blob=json.dumps(q,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>GDG Tech Challenge — Offline Backup</title>
<style>
:root{--ink:#1e1e1e;--blue:#c3ecf6;--green:#ccf6c5;--red:#f8d8d8;--yellow:#ffe7a5}
*{box-sizing:border-box}body{margin:0;background:#f0f0f0;color:var(--ink);font-family:Arial,system-ui,sans-serif}main{max-width:1500px;margin:auto;min-height:100vh;padding:35px 45px;display:flex;flex-direction:column;gap:25px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:2px solid;padding-bottom:16px}.label{font-family:monospace;font-size:15px;font-weight:700}.hero{font-size:clamp(32px,4.5vw,70px);line-height:1.08;letter-spacing:-.05em;max-width:1200px;margin:0}.code{background:#1e1e1e;color:white;padding:20px;border-radius:20px;font-family:monospace;font-size:clamp(15px,2vw,24px);white-space:pre-wrap;overflow-wrap:anywhere}.answers{display:grid;grid-template-columns:1fr 1fr;gap:15px}.answer{border:2px solid var(--ink);border-radius:22px;padding:20px;min-height:110px;display:flex;align-items:center;gap:20px;font-size:clamp(19px,2.2vw,32px);font-weight:700}.answer:nth-child(1){background:var(--blue)}.answer:nth-child(2){background:var(--red)}.answer:nth-child(3){background:var(--yellow)}.answer:nth-child(4){background:var(--green)}.answer b{border:2px solid;padding:14px 20px;border-radius:12px;background:white}.answer.good{outline:6px solid #34a853;outline-offset:2px}.answer.wrong{opacity:.35}.explanation{background:var(--green);padding:16px 22px;border:2px solid;border-radius:15px;font-size:22px;line-height:1.3}.buttons{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:auto;border-top:2px solid;padding-top:20px}button{font:inherit;background:white;color:var(--ink);border:2px solid var(--ink);border-radius:13px;padding:13px 18px;min-height:50px;font-weight:bold;cursor:pointer}button.primary{background:var(--ink);color:white}button:disabled{opacity:.4;cursor:default}.time{font-family:monospace;font-size:40px;font-weight:700;margin-left:auto}.helper{font-size:13px;color:#555}@media(max-width:750px){main{padding:20px}.answers{grid-template-columns:1fr}.answer{min-height:70px}}@media print{.buttons{display:none}}
</style></head><body><main><header class="top"><div class="label">// GDG ON CAMPUS · SAPIENZA / OFFLINE FALLBACK</div><div class="label" id="counter"></div></header><div class="label" id="category"></div><h1 class="hero" id="question"></h1><pre class="code" id="code" style="display:none"></pre><section class="answers" id="answers"></section><div class="explanation" id="explanation" style="display:none"></div><footer class="buttons"><button id="prev">← Previous</button><button class="primary" id="reveal">Reveal answer (Space)</button><button id="next">Next →</button><button id="clock">Start timer</button><span class="time" id="time"></span><div class="helper">Use this file if the campus Wi-Fi blocks LAN multiplayer. Collect A/B/C/D via hands or cards.</div></footer></main>
<script>
const qs=__QUESTIONS__;let n=0,revealed=false,remaining=0,clock=null;
const el=id=>document.getElementById(id);
const sec=()=>{clearInterval(clock);clock=null;remaining=qs[n].time_sec;el('time').textContent=remaining+'s'};
function render(){let q=qs[n];el('counter').textContent=(n+1)+' / '+qs.length;el('category').textContent='// '+q.category+' · '+q.difficulty.toUpperCase();el('question').textContent=q.question;el('code').style.display=q.code?'block':'none';el('code').textContent=q.code||'';el('answers').replaceChildren(...q.options.map((opt,i)=>{let x=document.createElement('div');x.className='answer'+(revealed?(i===q.correct_index?' good':' wrong'):'');let b=document.createElement('b');b.textContent='ABCD'[i];x.append(b,document.createTextNode(opt));return x}));el('explanation').textContent=q.explanation;el('explanation').style.display=revealed?'block':'none';el('reveal').textContent=revealed?'Hide answer (Space)':'Reveal answer (Space)';el('prev').disabled=n===0;el('next').disabled=n===qs.length-1;}
const jump=delta=>{n=Math.min(qs.length-1,Math.max(0,n+delta));revealed=false;sec();render()};
el('prev').onclick=()=>jump(-1);el('next').onclick=()=>jump(1);el('reveal').onclick=()=>{revealed=!revealed;render()};el('clock').onclick=()=>{sec();clock=setInterval(()=>{remaining=Math.max(0,remaining-1);el('time').textContent=remaining+'s';if(!remaining){clearInterval(clock);clock=null;}},1000)};
document.addEventListener('keydown',e=>{if(e.target.tagName==='BUTTON')return;if(e.key==='ArrowRight')jump(1);else if(e.key==='ArrowLeft')jump(-1);else if(e.code==='Space'){e.preventDefault();el('reveal').click();}});sec();render();
</script></body></html>'''.replace('__QUESTIONS__',blob)
(root/'OFFLINE-BACKUP.html').write_text(html,encoding='utf-8')
print('Created',root/'OFFLINE-BACKUP.html')
